-- CH-45: the global report catalog and the report id of an audit row (DEC-183, DEC-198).
-- Additive.
--
-- "Reporte" has no "tenantId" column and no foreign key to "Tenant", like "Plantilla": it is
-- a catalog shared by every tenant. Its id is generated by the Prisma client (`@default(uuid())`),
-- as for "Plantilla", so the column has no database default.
-- "RegistroEjecucion" triggers fire on UPDATE, DELETE and TRUNCATE only, so ADD COLUMN is
-- allowed and existing rows read null. The column has no foreign key, like "plantillaId".
-- Rollback (after reverting the code units):
--   ALTER TABLE "RegistroEjecucion" DROP COLUMN "reporteId";
--   DROP TABLE "Reporte";

-- CreateTable
CREATE TABLE "Reporte" (
    "id" TEXT NOT NULL,
    "nombre" TEXT NOT NULL,
    "titulo" TEXT NOT NULL,
    "descripcion" TEXT,
    "sql" TEXT NOT NULL,
    "entidades" JSONB NOT NULL,
    "visualizacion" TEXT NOT NULL,
    "columnas" JSONB NOT NULL,
    "periodo" JSONB,

    CONSTRAINT "Reporte_pkey" PRIMARY KEY ("id")
);

-- AlterTable
ALTER TABLE "RegistroEjecucion" ADD COLUMN "reporteId" TEXT;
